func (syncViewWhere[Q]) AliasedAs(alias string) syncViewWhere[Q] {
	return buildSyncViewWhere[Q](buildSyncViewColumns(alias))
}

func buildSyncViewWhere[Q psql.Filterable](cols syncViewColumns) syncViewWhere[Q] {
	return syncViewWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		Subject:     psql.Where[Q, string](cols.Subject.Expression),
		ContainerID: psql.Where[Q, string](cols.ContainerID.Expression),
		Sequence:    psql.Where[Q, int64](cols.Sequence.Expression),
		R:           syncViewWhereR[Q]{cols: cols},
	}
}

// syncViewWhereR holds the relationship-based filters of
// syncViewWhere under the R namespace — mirroring the model's
